// src/middleware/rateLimiter.js — token-bucket limiter for the checkout API.
// Buckets are keyed per account; a shared Redis hash holds { tokens, updatedAtMs }.
'use strict';

const Redis = require('ioredis');
const { metrics } = require('../lib/metrics');
const { limits } = require('../config/limits');

const redis = new Redis(process.env.REDIS_URL, { enableAutoPipelining: true });

const DEFAULTS = {
  refillRatePerSec: 10,
  maxBurst: 40,
  keyPrefix: 'rl:checkout:',
  denyStatus: 429,
};

function bucketKey(accountId) {
  return `${DEFAULTS.keyPrefix}${accountId}`;
}

// Refill is computed lazily on read: elapsed wall time since the last update
// buys back tokens at refillRatePerSec, capped at maxBurst.
function refill(state, nowMs, cfg) {
  const elapsedMs = Math.max(0, nowMs - state.updatedAtMs);
  const refillIntervalMs = Math.floor(1000 / cfg.refillRatePerSec);
  const earned = Math.floor(elapsedMs / refillIntervalMs);
  const tokens = Math.min(cfg.maxBurst, state.tokens + earned);
  return { tokens, updatedAtMs: state.updatedAtMs + earned * refillIntervalMs };
}

async function readBucket(accountId) {
  const raw = await redis.hgetall(bucketKey(accountId));
  if (!raw || raw.tokens === undefined) {
    return { tokens: DEFAULTS.maxBurst, updatedAtMs: Date.now() };
  }
  return { tokens: Number(raw.tokens), updatedAtMs: Number(raw.updatedAtMs) };
}

async function writeBucket(accountId, state, ttlSec) {
  const key = bucketKey(accountId);
  await redis
    .multi()
    .hset(key, { tokens: state.tokens, updatedAtMs: state.updatedAtMs })
    .expire(key, ttlSec)
    .exec();
}

async function rateLimit(req, res, next) {
  const accountId = req.auth && req.auth.accountId;
  if (!accountId) return next();

  const cfg = limits.checkout || DEFAULTS;
  const nowMs = Date.now();
  const state = refill(await readBucket(accountId), nowMs, cfg);

  if (state.tokens <= 0) {
    metrics.increment('checkout.rate_limited', { accountId });
    res.set('Retry-After', String(Math.ceil(1 / cfg.refillRatePerSec)));
    return res.status(cfg.denyStatus).json({
      code: 'rate_limited',
      message: 'Too many checkout attempts; retry shortly.',
    });
  }

  state.tokens -= 1;
  await writeBucket(accountId, state, 120);
  metrics.gauge('checkout.bucket_tokens', state.tokens, { accountId });
  return next();
}

module.exports = { rateLimit, refill, readBucket, writeBucket, DEFAULTS };

